-- ============================================================================
-- DC Beastmaster - hunter pet catalog roster
-- ============================================================================
-- Drives the DC-Collection "Beastmaster" tab (server module BEAST). The server
-- module joins each creature_id against creature_template for display id / family
-- / exotic flag at runtime and SKIPS missing/family-0 rows, so a stale row is
-- harmless. Adopting reuses Player::CreatePet().
--
-- Bulk imported from azerothcore/mod-npc-beastmaster (beastmaster_tames_inserts.sql,
-- 1060 stock WotLK beasts, all verified present + tameable in the DarkChaos world DB
-- 2026-07-14 -- 92 exotic). rarity = client item-quality (1 normal, 4 exotic);
-- category = WotLK family label. All stock 3.3.5 models (no downport).
-- ============================================================================

CREATE TABLE IF NOT EXISTS `dc_beastmaster_pets`
(
    `creature_id` INT UNSIGNED NOT NULL COMMENT 'creature_template.entry of the adoptable pet',
    `category`    VARCHAR(32)  NOT NULL DEFAULT 'Beast' COMMENT 'UI grouping label (WotLK family)',
    `rarity`      TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'client item-quality 0-6 for list color',
    `source_text` VARCHAR(128) NOT NULL DEFAULT '' COMMENT 'flavor: where the beast is from',
    `sort_order`  INT NOT NULL DEFAULT 0 COMMENT 'ascending display order',
    `enabled`     TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '0 hides the row',
    PRIMARY KEY (`creature_id`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = 'DC Beastmaster adoptable hunter pet roster';

